import csv
rows=list(csv.DictReader(open('t02_eurostat_raw.csv')))
print(len(rows))
print(rows[0].keys())
inds={}
for r in rows: inds.setdefault(r['indicator_id'],r['indicator_name'])
print(len(inds))
for k,v in inds.items(): print(k,'|',v)
cities={}
for r in rows: cities.setdefault(r['city_id'],r['city_name'])
print(len(cities))
ys=sorted(set(r['year'] for r in rows)); print(ys)
import collections
c=collections.Counter((r['city_id'],r['year'],r['indicator_id']) for r in rows)
print('dups',[k for k,v in c.items() if v>1][:10])
print('units',collections.Counter(r['unit'] for r in rows))
# whitespace/structure checks
print('empty vals',sum(1 for r in rows if r['value']==''))
# weird chars
for r in rows:
    for f in ('city_name','value'):
        if ',' in r[f] or '\"' in r[f] or '\n' in r[f]:
            print('special',repr(r[f])); break
""}

