{"command":"cd outputs && python3 -c "
import csv,collections
rows=list(csv.DictReader(open('t02_eurostat_raw.csv')))
cities={}
for r in rows: cities.setdefault(r['city_id'],set()).add(r['city_name'])
print([c for c,v in cities.items() if len(v)>1])
pairs=set((r['city_id'],r['year']) for r in rows)
print(len(pairs), len(cities), len(set(r['year'] for r in rows)))
# which pairs missing
allp=set((c,y) for c in cities for y in ['2022','2023','2024','2025'])
print('missing',sorted(allp-pairs))
order=[]
for r in rows:
    if r['indicator_id'] not in order: order.append(r['indicator_id'])
print(order)
# per indicator pair coverage
cov=collections.defaultdict(set)
for r in rows: cov[r['indicator_id']].add((r['city_id'],r['year']))
for k in order: print(k,len(cov[k]))
""}

